33	vx_result_t Buffer::create(Device* dev, uint64_t size, uint32_t flags,
34	                           Buffer** out) {
35	    if (!dev || !out || size == 0) return VX_ERR_INVALID_VALUE;
36	    uint64_t dev_addr = 0;
37	    auto r = dev->mem_alloc(size, flags, &dev_addr);
38	    if (r != VX_SUCCESS) return r;
39	    *out = new Buffer(dev, dev_addr, size, flags);
40	    return VX_SUCCESS;
41	}
