43	vx_result_t Buffer::reserve(Device* dev, uint64_t address, uint64_t size,
44	                            uint32_t flags, Buffer** out) {
45	    if (!dev || !out || size == 0) return VX_ERR_INVALID_VALUE;
46	    auto r = dev->mem_reserve(address, size, flags);
47	    if (r != VX_SUCCESS) return r;
48	    *out = new Buffer(dev, address, size, flags);
49	    return VX_SUCCESS;
50	}
