52	vx_result_t Buffer::access(uint64_t off, uint64_t size, uint32_t /*flags*/) {
53	    if (off + size > size_) return VX_ERR_INVALID_VALUE;
54	    // Access permissions are not tracked by the transport HAL — the CP is
55	    // the sole memory engine and the common-core allocator owns the map.
56	    return VX_SUCCESS;
57	}
58	
59	vx_result_t Buffer::map_reserve(uint64_t off, uint64_t size, uint32_t flags,
60	                                void** out) {
61	    if (!out)                return VX_ERR_INVALID_VALUE;
62	    if (off + size > size_)  return VX_ERR_INVALID_VALUE;
63	
64	    std::lock_guard<std::mutex> g(map_mu_);
65	    if (mapped_) return VX_ERR_NOT_SUPPORTED;   // single mapping at a time
66	
67	    // Allocate a host mirror. map_commit prefills it from the device for
68	    // READ maps; unmap uploads it back for WRITE maps. Correct (no
69	    // use-after-free) but loses the zero-copy benefit pinned memory
70	    // would provide on real hardware.
71	    host_mirror_ = std::malloc(size);
72	    if (!host_mirror_) return VX_ERR_OUT_OF_HOST_MEMORY;
73	
74	    mapped_off_   = off;
75	    mapped_size_  = size;
76	    mapped_flags_ = flags;
77	    mapped_       = true;
78	    *out = host_mirror_;
79	    return VX_SUCCESS;
80	}
81	
82	vx_result_t Buffer::map_commit() {
83	    std::lock_guard<std::mutex> g(map_mu_);
84	    if (!mapped_) return VX_ERR_INVALID_VALUE;
85	    if ((mapped_flags_ & VX_MEM_READ) && mapped_size_ != 0) {
86	        return device_->dev_read(host_mirror_, dev_addr_ + mapped_off_,
87	                                 mapped_size_);
88	    }
89	    return VX_SUCCESS;
90	}
91	
92	void Buffer::map_cancel() {
93	    std::lock_guard<std::mutex> g(map_mu_);
94	    if (mapped_) {
95	        std::free(host_mirror_);
96	        host_mirror_ = nullptr;
97	        mapped_      = false;
98	    }
99	}
