101	vx_result_t Buffer::map(uint64_t off, uint64_t size, uint32_t flags,
102	                        void** out) {
103	    auto r = this->map_reserve(off, size, flags, out);
104	    if (r != VX_SUCCESS) return r;
105	    r = this->map_commit();
106	    if (r != VX_SUCCESS) this->map_cancel();
107	    return r;
108	}
109	
110	vx_result_t Buffer::unmap(void* host_ptr) {
111	    std::lock_guard<std::mutex> g(map_mu_);
112	    if (!mapped_ || host_ptr != host_mirror_)
113	        return VX_ERR_INVALID_VALUE;
114	    vx_result_t r = VX_SUCCESS;
115	    if (mapped_flags_ & VX_MEM_WRITE) {
116	        r = device_->dev_write(dev_addr_ + mapped_off_, host_mirror_,
117	                               mapped_size_);
118	    }
119	    std::free(host_mirror_);
120	    host_mirror_ = nullptr;
121	    mapped_      = false;
122	    return r;
123	}
