8	// VMManager is always compiled into libvortex.so — VM is a runtime device
9	// property, not a compile-time #ifdef. The Sv32/Sv39 split comes from
10	// VX_VM_ADDR_MODE (VX_types.h); HW-private VX_config.h is not included.
11	#include <VX_types.h>
12	#include "vm.h"
13	
14	#include <vortex.h>
15	#include <common.h>
16	#include <util.h>
17	#include <cassert>
18	#include <cstdlib>
19	#include <cstring>
20	#include <iostream>
21	
22	using namespace vortex;
23	
24	namespace {
25	// Translate the runtime's VX_MEM_{READ,WRITE} access-flag bitmask into PTE
26	// permission bits (V|R always; W if WRITE).
27	uint32_t pte_flags_from_access(uint32_t access_flags) {
28	  uint32_t pte = PTE_V | PTE_R;
29	  if (access_flags & VX_MEM_WRITE)
30	    pte |= PTE_W;
31	  return pte;
32	}
33	
34	// Ceil-log2 — used for the per-level VPN field width.
35	constexpr unsigned vm_clog2(uint64_t n) {
36	  unsigned r = 0;
37	  while ((uint64_t(1) << r) < n) ++r;
38	  return r;
39	}
40	// VPN bits per page-table level = log2(PTEs per table). SV39 -> 9, SV32 -> 10.
41	constexpr unsigned VM_VPN_BITS = vm_clog2(VX_VM_PT_SIZE / VX_VM_PTE_SIZE);
42	} // namespace
43	
44	VMManager::VMManager(DeviceMemIO* dev_io)
45	    : dev_io_(dev_io),
46	      satp_(nullptr),
47	      page_table_mem_(nullptr),
48	      virtual_mem_(nullptr) {
49	  const char* randomize_env = std::getenv("VORTEX_RANDOMIZE_VA");
50	  randomize_va_ = (randomize_env != nullptr && std::atoi(randomize_env) != 0);
51	
52	  const char* seed_env = std::getenv("VORTEX_VA_SEED");
53	  uint64_t seed = seed_env ? std::atoll(seed_env) : 0x12345678ULL;
54	  rng_.seed(seed);
55	
56	  if (randomize_va_) {
57	    std::cout << "[VM] Virtual address randomization ENABLED (seed=0x"
58	              << std::hex << seed << std::dec << ")" << std::endl;
59	  }
60	}
61	
62	VMManager::~VMManager() {
63	  delete virtual_mem_;
64	  delete page_table_mem_;
65	}
66	
67	int VMManager::virtual_mem_reserve(uint64_t dev_addr, uint64_t size, int /*flags*/) {
68	  CHECK_ERR(virtual_mem_->reserve(dev_addr, size), {
69	    return err;
70	  });
71	  DBGPRINT("[RT:mem_reserve] addr: 0x%lx, size:0x%lx\n", dev_addr, size);
72	  return 0;
73	}
74	
75	int VMManager::init() {
76	  uint64_t pt_addr = 0;
77	  std::cout << "VMManager Initialization..." << std::endl;
78	  page_table_mem_ = new MemoryAllocator(VX_MEM_PAGE_TABLE_BASE_ADDR, VX_VM_PT_SIZE_LIMIT, VX_VM_PAGE_SIZE, CACHE_BLOCK_SIZE);
79	  if (page_table_mem_ == nullptr)
80	    return 1;
81	
82	  uint64_t virtual_mem_size = (GLOBAL_MEM_SIZE - ALLOC_BASE_ADDR);
83	#if VX_VM_ADDR_MODE == SV32
84	  // Keep VAs within the 32-bit address space.
85	  uint64_t max_va_end = 0x100000000ULL;
86	  if (ALLOC_BASE_ADDR + virtual_mem_size > max_va_end) {
87	    virtual_mem_size = max_va_end - ALLOC_BASE_ADDR;
88	  }
89	#endif
90	  virtual_mem_ = new MemoryAllocator(ALLOC_BASE_ADDR, virtual_mem_size, VX_VM_PAGE_SIZE, CACHE_BLOCK_SIZE);
91	  if (virtual_mem_ == nullptr)
92	    return 1;
93	
94	  if (VX_VM_ADDR_MODE == BARE) {
95	    DBGPRINT("[RT:init_VM] VA_MODE = BARE MODE(addr= 0x0)\n");
96	  } else {
97	    CHECK_ERR(alloc_page_table(&pt_addr), { return err; });
98	  }
99	
100	  // Stash a local SATP record so need_trans / page_table_walk see the
101	  // PT base. The simulator's hardware MMU sees SATP via the kernel's
102	  // csrw at boot — VMManager does not push it into the simulator.
103	  satp_ = std::make_unique<SATP_t>(pt_addr, /*asid=*/0);
104	
105	  if (VX_VM_ADDR_MODE != BARE) {
106	    // Identity-map system regions that are PA-addressed by the kernel
107	    // and runtime: IO MMIO range and the high region containing the
108	    // page table + per-warp stacks. The kernel image is mapped later
109	    // via mem_reserve() once the loader knows its extents.
110	    CHECK_ERR(install_identity_map(0, VX_MEM_USER_BASE_ADDR), { return err; });
111	    CHECK_ERR(install_identity_map(VX_MEM_PAGE_TABLE_BASE_ADDR,
112	                                   GLOBAL_MEM_SIZE - VX_MEM_PAGE_TABLE_BASE_ADDR), {
113	      return err;
114	    });
115	  }
116	  // install_identity_map() already flushed; an extra flush here is a
117	  // cheap no-op if nothing else dirtied the shadow.
118	  return flush();
119	}
120	
121	bool VMManager::need_trans(uint64_t dev_pAddr) {
122	  (void)dev_pAddr;
123	  // System PA regions (IO, kernel image, page table, stack) are
124	  // identity-mapped at boot, so every address goes through PTW
125	  // except those issued before SATP is set or in BARE mode.
126	  if (this->is_satp_unset() || get_mode() == BARE)
127	    return false;
128	  return true;
129	}
130	
131	uint64_t VMManager::map_p2v(uint64_t ppn, uint32_t flags) {
132	  if (addr_mapping.find(ppn) != addr_mapping.end())
133	    return addr_mapping[ppn];
134	
135	  uint64_t vpn;
136	  if (randomize_va_) {
137	    const int MAX_ATTEMPTS = 1000;
138	    bool allocated = false;
139	    for (int attempt = 0; attempt < MAX_ATTEMPTS; ++attempt) {
140	      uint64_t va_range_start = ALLOC_BASE_ADDR;
141	      uint64_t va_range_end = VX_MEM_PAGE_TABLE_BASE_ADDR;
142	#if VX_VM_ADDR_MODE == SV32
143	      uint64_t max_va = 0xFFFFFFFFULL;
144	      if (va_range_end > max_va)
145	        va_range_end = max_va;
146	#endif
147	      uint64_t va_range_size = va_range_end - va_range_start;
148	      uint64_t max_pages = va_range_size >> VX_VM_PAGE_LOG2_SIZE;
149	      std::uniform_int_distribution<uint64_t> dist(0, max_pages - 1);
150	      uint64_t random_page_offset = dist(rng_);
151	      uint64_t candidate_va = va_range_start + (random_page_offset << VX_VM_PAGE_LOG2_SIZE);
152	
153	      bool in_use = false;
154	      for (const auto& mapping : addr_mapping) {
155	        if (mapping.second == (candidate_va >> VX_VM_PAGE_LOG2_SIZE)) {
156	          in_use = true;
157	          break;
158	        }
159	      }
160	      if (!in_use && virtual_mem_->reserve(candidate_va, VX_VM_PAGE_SIZE) == 0) {
161	        vpn = candidate_va >> VX_VM_PAGE_LOG2_SIZE;
162	        allocated = true;
163	        break;
164	      }
165	    }
166	    if (!allocated) {
167	      virtual_mem_->allocate(VX_VM_PAGE_SIZE, &vpn);
168	      vpn >>= VX_VM_PAGE_LOG2_SIZE;
169	    }
170	  } else {
171	    virtual_mem_->allocate(VX_VM_PAGE_SIZE, &vpn);
172	    vpn >>= VX_VM_PAGE_LOG2_SIZE;
173	  }
174	
175	  CHECK_ERR(update_page_table(ppn, vpn, pte_flags_from_access(flags)), );
176	  addr_mapping[ppn] = vpn;
177	  flush();
178	  return vpn;
179	}
180	
181	int VMManager::phy_to_virt_map(uint64_t size, uint64_t* dev_pAddr, uint32_t flags) {
182	  if (!need_trans(*dev_pAddr))
183	    return 0;
184	
185	  uint64_t init_pAddr = *dev_pAddr;
186	  // Round up: a sub-page allocation still needs one PTE. A plain
187	  // `size >> PAGE_LOG2` truncates to 0 for any buffer < 4 KB, leaving
188	  // it unmapped.
189	  uint64_t num_pages = (size + VX_VM_PAGE_SIZE - 1) >> VX_VM_PAGE_LOG2_SIZE;
190	  uint64_t base_ppn = init_pAddr >> VX_VM_PAGE_LOG2_SIZE;
191	
192	  uint64_t base_vpn;
193	  if (addr_mapping.find(base_ppn) != addr_mapping.end()) {
194	    base_vpn = addr_mapping[base_ppn];
195	  } else {
196	    uint64_t base_va = 0;
197	    if (randomize_va_) {
198	      const int MAX_ATTEMPTS = 1000;
199	      bool allocated = false;
200	      for (int attempt = 0; attempt < MAX_ATTEMPTS && !allocated; ++attempt) {
201	        uint64_t va_range_start = ALLOC_BASE_ADDR;
202	        uint64_t va_range_end = VX_MEM_PAGE_TABLE_BASE_ADDR;
203	#if VX_VM_ADDR_MODE == SV32
204	        uint64_t max_va = 0xFFFFFFFFULL;
205	        if (va_range_end > max_va)
206	          va_range_end = max_va;
207	#endif
208	        uint64_t va_range_size = va_range_end - va_range_start;
209	        uint64_t max_pages = (va_range_size >> VX_VM_PAGE_LOG2_SIZE) - num_pages;
210	        std::uniform_int_distribution<uint64_t> dist(0, max_pages - 1);
211	        uint64_t random_page_offset = dist(rng_);
212	        uint64_t candidate_va = va_range_start + (random_page_offset << VX_VM_PAGE_LOG2_SIZE);
213	
214	        bool range_available = true;
215	        for (uint64_t i = 0; i < num_pages && range_available; ++i) {
216	          uint64_t test_vpn = (candidate_va >> VX_VM_PAGE_LOG2_SIZE) + i;
217	          for (const auto& mapping : addr_mapping) {
218	            if (mapping.second == test_vpn) {
219	              range_available = false;
220	              break;
221	            }
222	          }
223	        }
224	        if (range_available && virtual_mem_->reserve(candidate_va, size) == 0) {
225	          base_va = candidate_va;
226	          allocated = true;
227	        }
228	      }
229	      if (!allocated) {
230	        base_va = 0;
231	        CHECK_ERR(virtual_mem_->allocate(size, &base_va), );
232	      }
233	    } else {
234	      base_va = 0;
235	      CHECK_ERR(virtual_mem_->allocate(size, &base_va), );
236	    }
237	    base_vpn = base_va >> VX_VM_PAGE_LOG2_SIZE;
238	  }
239	
240	  uint64_t init_vAddr = (base_vpn << VX_VM_PAGE_LOG2_SIZE) | (init_pAddr & ((1 << VX_VM_PAGE_LOG2_SIZE) - 1));
241	
242	  for (uint64_t i = 0; i < num_pages; i++) {
243	    uint64_t ppn = base_ppn + i;
244	    uint64_t vpn = base_vpn + i;
245	    if (addr_mapping.find(ppn) == addr_mapping.end()) {
246	      CHECK_ERR(update_page_table(ppn, vpn, pte_flags_from_access(flags)), );
247	      addr_mapping[ppn] = vpn;
248	    }
249	  }
250	
251	  assert(page_table_walk(init_vAddr) == init_pAddr && "VA->PA round-trip mismatch");
252	
253	  *dev_pAddr = init_vAddr;
254	  return flush();
255	}
256	
257	uint8_t VMManager::alloc_page_table(uint64_t* pt_addr) {
258	  CHECK_ERR(page_table_mem_->allocate(VX_VM_PT_SIZE, pt_addr), { return err; });
259	  // Lazily materialize the shadow page (zero-initialized) and mark
260	  // dirty so flush() pushes the zeros to device memory at least once.
261	  auto& page = touch_pt_page(*pt_addr);
262	  std::memset(page.data(), 0, page.size());
263	  return 0;
264	}
265	
266	int16_t VMManager::update_page_table(uint64_t ppn, uint64_t vpn, uint32_t pte_flag, uint8_t leaf_level) {
267	#if VX_VM_ADDR_MODE == SV39
268	  assert((((ppn >> 44) == 0) && ((vpn >> 27) == 0)) && "Upper bits are not zero!");
269	#else
270	  assert((((ppn >> 20) == 0) && ((vpn >> 20) == 0)) && "Upper 12 bits are not zero!");
271	#endif
272	  assert(leaf_level < VX_VM_PT_LEVEL && "leaf_level out of range");
273	  int i = VX_VM_PT_LEVEL - 1;
274	  vAddr_t vaddr(vpn << VX_VM_PAGE_LOG2_SIZE);
275	  uint64_t pte_addr = 0, pte_bytes = 0;
276	  uint64_t pt_addr = 0;
277	  uint64_t cur_base_ppn = get_base_ppn();
278	
279	  while (i >= 0) {
280	    pte_addr = (cur_base_ppn * VX_VM_PT_SIZE) + (vaddr.vpn[i] * VX_VM_PTE_SIZE);
281	    pte_bytes = read_pte(pte_addr);
282	    PTE_t pte_chk(pte_bytes);
283	    bool valid = (pte_chk.v == 1) && ((pte_bytes & 0xFFFFFFFF) != 0xbaadf00d);
284	    if (valid && (pte_chk.r || pte_chk.w || pte_chk.x)) {
285	      // An existing leaf (super)page already maps this VA — a PTE with any of
286	      // R/W/X set is a leaf, not a pointer to the next level (RISC-V priv
287	      // spec). Descending into it would walk mapped data as a page table.
288	      // Re-mapping is idempotent when the existing leaf already yields the
289	      // requested translation — install_identity_map legitimately re-covers a
290	      // sub-range of a coarser identity superpage installed by
291	      // VMManager::init() — while a different target is a genuine conflict.
292	      uint64_t span = uint64_t(1) << (i * VM_VPN_BITS);   // 4 KB pages per level-i page
293	      uint64_t mapped_ppn = (pte_chk.ppn & ~(span - 1)) | (vpn & (span - 1));
294	      return (mapped_ppn == ppn) ? 0 : -1;
295	    }
296	    if (valid) {
297	      cur_base_ppn = pte_chk.ppn;   // interior node — descend
298	    } else {
299	      if (i == (int)leaf_level) {
300	        // Leaf: caller supplies the raw PTE permission bits.
301	        PTE_t new_pte(ppn << VX_VM_PAGE_LOG2_SIZE, pte_flag);
302	        write_pte(pte_addr, new_pte.pte_bytes);
303	        break;
304	      } else {
305	        // Interior: allocate next-level table; PTE_V only (RWX cleared
306	        // marks it as a pointer to the next-level table per the spec).
307	        alloc_page_table(&pt_addr);
308	        PTE_t new_pte(pt_addr, PTE_V);
309	        write_pte(pte_addr, new_pte.pte_bytes);
310	        cur_base_ppn = new_pte.ppn;
311	      }
312	    }
313	    i--;
314	  }
315	  return 0;
316	}
317	
318	int VMManager::install_identity_map(uint64_t addr, uint64_t size) {
319	  // Per-level page coverage: L0 = VX_VM_PAGE_SIZE, each higher level
320	  // multiplies by PT entries-per-table. SV32: L1=4MB. SV39: L1=2MB, L2=1GB.
321	  constexpr uint64_t PT_FANOUT = VX_VM_PT_SIZE / VX_VM_PTE_SIZE;
322	  uint64_t level_size[VX_VM_PT_LEVEL];
323	  level_size[0] = VX_VM_PAGE_SIZE;
324	  for (uint8_t l = 1; l < VX_VM_PT_LEVEL; ++l) {
325	    level_size[l] = level_size[l - 1] * PT_FANOUT;
326	  }
327	
328	  // Identity-mapped system regions get full R/W/X; the host-side ACL
329	  // (set via mem_access) is the actual permission boundary.
330	  constexpr uint32_t IDENTITY_PTE_FLAGS = PTE_V | PTE_R | PTE_W | PTE_X;
331	
332	  (void)virtual_mem_->reserve(addr, size);
333	
334	  uint64_t cur = addr;
335	  uint64_t end = addr + size;
336	  while (cur < end) {
337	    uint64_t remaining = end - cur;
338	    uint8_t leaf_level = 0;
339	    for (int l = VX_VM_PT_LEVEL - 1; l > 0; --l) {
340	      if ((cur % level_size[l]) == 0 && remaining >= level_size[l]) {
341	        leaf_level = (uint8_t)l;
342	        break;
343	      }
344	    }
345	    uint64_t vpn = cur >> VX_VM_PAGE_LOG2_SIZE;
346	    CHECK_ERR(update_page_table(vpn, vpn, IDENTITY_PTE_FLAGS, leaf_level), {
347	      return err;
348	    });
349	    cur += level_size[leaf_level];
350	  }
351	  return flush();
352	}
353	
354	uint64_t VMManager::page_table_walk(uint64_t vAddr_bits) {
355	  if (!need_trans(vAddr_bits))
356	    return vAddr_bits;
357	
358	  uint8_t level = VX_VM_PT_LEVEL;
359	  int i = level - 1;
360	  vAddr_t vaddr(vAddr_bits);
361	  uint64_t pte_addr = 0, pte_bytes = 0;
362	  uint64_t cur_base_ppn = get_base_ppn();
363	
364	  while (true) {
365	    pte_addr = (cur_base_ppn * VX_VM_PT_SIZE) + (vaddr.vpn[i] * VX_VM_PTE_SIZE);
366	    pte_bytes = read_pte(pte_addr);
367	    PTE_t pte(pte_bytes);
368	    assert(((pte.pte_bytes & 0xFFFFFFFF) != 0xbaadf00d) && "uninitialized PTE");
369	
370	    if ((pte.v == 0) | ((pte.r == 0) & (pte.w == 1))) {
371	      throw Page_Fault_Exception("[RT:PTW] invalid entry");
372	    }
373	    if ((pte.r == 0) & (pte.w == 0) & (pte.x == 0)) {
374	      i--;
375	      if (i < 0)
376	        throw Page_Fault_Exception("[RT:PTW] no leaf node");
377	      cur_base_ppn = pte.ppn;
378	      continue;
379	    }
380	    if (pte.r == 0)
381	      throw Page_Fault_Exception("[RT:PTW] permission");
382	    cur_base_ppn = pte.ppn;   // leaf found at level i
383	    break;
384	  }
385	  // Reconstruct the physical address. For a leaf found at level i > 0 (a
386	  // mega/gigapage) the low VX_VM_PAGE_LOG2_SIZE + i*VM_VPN_BITS address bits
387	  // are the offset *within* the superpage and must come from the VA, not
388	  // from the (superpage-aligned) leaf PPN. For a 4 KB leaf (i == 0) this
389	  // reduces to the ordinary ppn<<12 | page-offset.
390	  const uint64_t off_mask =
391	      (uint64_t(1) << (VX_VM_PAGE_LOG2_SIZE + i * VM_VPN_BITS)) - 1;
392	  return ((cur_base_ppn << VX_VM_PAGE_LOG2_SIZE) & ~off_mask)
393	       | (vAddr_bits & off_mask);
394	}
395	
396	// -- shadow PT helpers --------------------------------------------------
397	
398	std::vector<uint8_t>& VMManager::touch_pt_page(uint64_t addr) {
399	  uint64_t page_pa = addr & ~(uint64_t)(VX_VM_PT_SIZE - 1);
400	  auto& page = shadow_pt_[page_pa];
401	  if (page.empty())
402	    page.resize(VX_VM_PT_SIZE, 0);
403	  dirty_pt_pages_.insert(page_pa);
404	  return page;
405	}
406	
407	const std::vector<uint8_t>* VMManager::peek_pt_page(uint64_t addr) const {
408	  uint64_t page_pa = addr & ~(uint64_t)(VX_VM_PT_SIZE - 1);
409	  auto it = shadow_pt_.find(page_pa);
410	  if (it == shadow_pt_.end())
411	    return nullptr;
412	  return &it->second;
413	}
414	
415	void VMManager::write_pte(uint64_t addr, uint64_t value) {
416	  auto& page = touch_pt_page(addr);
417	  uint64_t off = addr - (addr & ~(uint64_t)(VX_VM_PT_SIZE - 1));
418	  // Little-endian byte serialization, matching the device-side PTW
419	  // which fetches VX_VM_PTE_SIZE bytes from this address.
420	  for (uint64_t i = 0; i < VX_VM_PTE_SIZE; ++i) {
421	    page[off + i] = (value >> (i << 3)) & 0xff;
422	  }
423	}
424	
425	uint64_t VMManager::read_pte(uint64_t addr) {
426	  const auto* page = peek_pt_page(addr);
427	#if VX_VM_ADDR_MODE == SV32
428	  uint64_t mask = 0x00000000FFFFFFFFULL;
429	#else
430	  uint64_t mask = 0xFFFFFFFFFFFFFFFFULL;
431	#endif
432	  if (page == nullptr) {
433	    // Unallocated PT page reads as zero (matches device DRAM init
434	    // pattern from cache_init / fresh allocator state).
435	    return 0;
436	  }
437	  uint64_t off = addr - (addr & ~(uint64_t)(VX_VM_PT_SIZE - 1));
438	  uint64_t v = 0;
439	  for (uint64_t i = 0; i < VX_VM_PTE_SIZE; ++i) {
440	    v |= (uint64_t)(*page)[off + i] << (i << 3);
441	  }
442	  return v & mask;
443	}
444	
445	int VMManager::flush() {
446	  // One bulk device write per dirty PT page, minimizing DMA transactions.
447	  if (dirty_pt_pages_.empty())
448	    return 0;
449	  for (uint64_t page_pa : dirty_pt_pages_) {
450	    const auto& page = shadow_pt_[page_pa];
451	    dev_io_->write(page.data(), page_pa, page.size());
452	  }
453	  dirty_pt_pages_.clear();
454	  return 0;
455	}
