27	// Resolve the pinned-region size: compile-time default
28	// VX_CFG_VM_PINNED_REGION_SIZE, optionally overridden by the
29	// VORTEX_VM_PINNED_SIZE env var (decimal bytes). Returns 0 when VM is
30	// disabled at build time (the pinned-region carve-out is a no-op then —
31	// VX_MEM_PHYS has no effect without VM).
32	static uint64_t resolve_pinned_size() {
33	#if VX_CFG_VM_ENABLED
34	    uint64_t size = (uint64_t)VX_CFG_VM_PINNED_REGION_SIZE;
35	    if (const char* s = std::getenv("VORTEX_VM_PINNED_SIZE")) {
36	        char* end = nullptr;
37	        unsigned long long v = std::strtoull(s, &end, 0);
38	        if (end != s) size = (uint64_t)v;
39	    }
40	    // Bound at GLOBAL_MEM_SIZE/2 so the paged pool always has room.
41	    const uint64_t user_size = GLOBAL_MEM_SIZE - ALLOC_BASE_ADDR;
42	    if (size > user_size / 2) size = user_size / 2;
43	    // Round down to a page so the slab boundary is page-aligned (the
44	    // VM page-table walker installs leaf PTEs at page granularity).
45	    size &= ~uint64_t(RAM_PAGE_SIZE - 1);
46	    return size;
47	#else
48	    return 0;
49	#endif
50	}
