52	Device::Device(std::unique_ptr<Platform> plat)
53	    : platform_(std::move(plat)), cycle_freq_hz_(0),
54	      global_mem_(ALLOC_BASE_ADDR, GLOBAL_MEM_SIZE - ALLOC_BASE_ADDR,
55	                  RAM_PAGE_SIZE, CACHE_BLOCK_SIZE) {
56	    // cycle_freq_hz_=0 tells the ns conversion path to use the wall clock.
57	    // global_mem_ is the device-memory allocator — pure host-side address
58	    // bookkeeping; the CP DMAs to whatever addresses it hands out.
59	
60	    // Pinned slab: under VM, carve a fixed low-address region for
61	    // VX_MEM_PHYS allocations. Reserved out of global_mem_ so the
62	    // paged-pool side never hands out an address that collides with
63	    // an identity-mapped pinned buffer.
64	    pinned_size_ = resolve_pinned_size();
65	    if (pinned_size_ > 0) {
66	        pinned_base_ = ALLOC_BASE_ADDR;
67	        // Reserve the slab from global_mem_; the slab is owned by pinned_mem_.
68	        if (global_mem_.reserve(pinned_base_, pinned_size_) != 0) {
69	            // Should not fail at ctor time — global_mem_ was just constructed
70	            // and nothing else has touched it.
71	            pinned_size_ = 0;
72	            pinned_base_ = 0;
73	        } else {
74	            pinned_mem_.reset(new vortex::MemoryAllocator(
75	                pinned_base_, pinned_size_,
76	                RAM_PAGE_SIZE, CACHE_BLOCK_SIZE));
77	        }
78	    }
79	}
