107	vx_result_t Device::args_slot_acquire(uint64_t size, uint64_t* out_addr,
108	                                      bool* out_pooled) {
109	    if (!out_addr || !out_pooled) return VX_ERR_INVALID_VALUE;
110	    if (size > ARGS_SLOT_SIZE) {
111	        // Oversized args block — one-off allocation, not pooled.
112	        *out_pooled = false;
113	        return this->mem_alloc(size, /*VX_MEM_READ*/ 0x1, out_addr);
114	    }
115	    *out_pooled = true;
116	    {
117	        std::lock_guard<std::mutex> g(args_pool_mu_);
118	        if (!args_pool_free_.empty()) {
119	            *out_addr = args_pool_free_.back();
120	            args_pool_free_.pop_back();
121	            return VX_SUCCESS;
122	        }
123	    }
124	    // Pool empty — allocate a fresh pooled slot (recycled on release).
125	    return this->mem_alloc(ARGS_SLOT_SIZE, /*VX_MEM_READ*/ 0x1, out_addr);
126	}
