160	// ============================================================================
161	// Command Processor submission path. One source of truth for the CP wire
162	// protocol — every backend goes through this code via platform()->cp_reg_*
163	// (the register channel) and host_alloc/host_free (CP-visible host memory).
164	// The runtime writes commands straight through the ring's host pointer; the
165	// CP fetches and executes them.
166	// ============================================================================
167	
168	namespace {
169	// CP regfile offsets (CP-internal; backends translate to physical addrs).
170	// Matches VX_cp_axil_regfile.
171	constexpr uint32_t CP_REG_CTRL          = 0x000;
172	constexpr uint32_t CP_DEV_CAPS          = 0x008;  // {VM_ENABLED@24|TID|RING|NQ}
173	constexpr uint32_t CP_Q_RING_BASE_LO    = 0x100;
174	constexpr uint32_t CP_Q_RING_BASE_HI    = 0x104;
175	constexpr uint32_t CP_Q_HEAD_ADDR_LO    = 0x108;
176	constexpr uint32_t CP_Q_HEAD_ADDR_HI    = 0x10C;
177	constexpr uint32_t CP_Q_CMPL_ADDR_LO    = 0x110;
178	constexpr uint32_t CP_Q_CMPL_ADDR_HI    = 0x114;
179	constexpr uint32_t CP_Q_RING_SIZE_LOG2  = 0x118;
180	constexpr uint32_t CP_Q_CONTROL         = 0x11C;
181	constexpr uint32_t CP_Q_TAIL_LO         = 0x120;
182	constexpr uint32_t CP_Q_TAIL_HI         = 0x124;
183	constexpr uint32_t CP_Q_SEQNUM          = 0x128;
184	constexpr uint32_t CP_Q_LAST_DCR_RSP    = 0x130;
185	constexpr uint32_t CP_SATP_LO           = 0x028;  // CP DMA MMU page-table root
186	constexpr uint32_t CP_SATP_HI           = 0x02C;
187	
188	// CMD_MEM_* header flag (cmd_t.flags bit2 = F_MEM_PHYSICAL): device operand
189	// is physical — the MMU-aware CP DMA skips translation.
190	constexpr uint8_t  CP_MEM_FLAG_PHYSICAL = 0x04;
191	
192	constexpr uint32_t CP_RING_SIZE_LOG2 = 16;       // 64 KiB
193	constexpr uint32_t CP_RING_SIZE      = 1u << CP_RING_SIZE_LOG2;
194	constexpr uint8_t  CP_OPCODE_MEM_WRITE  = 0x01;
195	constexpr uint8_t  CP_OPCODE_MEM_READ   = 0x02;
196	constexpr uint8_t  CP_OPCODE_MEM_COPY   = 0x03;
197	constexpr uint8_t  CP_OPCODE_DCR_WR     = 0x04;
198	constexpr uint8_t  CP_OPCODE_DCR_RD     = 0x05;
199	constexpr uint8_t  CP_OPCODE_LAUNCH     = 0x06;
200	constexpr uint8_t  CP_OPCODE_EVT_SIG    = 0x08;
201	constexpr uint8_t  CP_OPCODE_EVT_WAIT   = 0x09;
202	constexpr uint8_t  CP_OPCODE_CACHE_FLUSH= 0x0A;
203	constexpr uint8_t  CP_OPCODE_LAUNCH_QMD = 0x0B;
204	constexpr uint8_t  CP_OPCODE_DRAW       = 0x0C;
205	constexpr std::size_t CP_CL_BYTES    = 64;
206	
207	// CMD_EVENT_WAIT comparison operations (encoded in arg2[1:0]).
208	// Mirrors hw/rtl/cp/VX_cp_pkg.sv:wait_op_e.
209	constexpr uint8_t  CP_WAIT_OP_EQ = 0;
210	constexpr uint8_t  CP_WAIT_OP_GE = 1;
211	constexpr uint8_t  CP_WAIT_OP_GT = 2;
212	constexpr uint8_t  CP_WAIT_OP_NE = 3;
213	
214	} // namespace
215	
216	// VMManager's device-memory port: PA-direct page-table I/O through the CP
217	// DMA. The `physical` flag bypasses the CP DMA's VA translation, so the
218	// page-table region itself is written/read at its true physical address.
219	class Device::CpMemIO : public vortex::DeviceMemIO {
220	public:
221	    explicit CpMemIO(Device* dev) : dev_(dev) {}
222	    void read(void* dst, uint64_t addr, size_t size) override {
223	        dev_->cp_submit_mem_read(dst, addr, size, /*physical=*/true);
224	    }
225	    void write(const void* src, uint64_t addr, size_t size) override {
226	        dev_->cp_submit_mem_write(addr, src, size, /*physical=*/true);
227	    }
228	private:
229	    Device* dev_;
230	};
231	
232	vx_result_t Device::cp_init() {
233	    // Ring + head + completion live in CP-visible host memory: the runtime
234	    // appends commands straight through the ring's host pointer and the CP
235	    // fetches them over its m_axi_host master — no per-command DMA.
236	    auto* p = platform();
237	    auto r = host_alloc(CP_RING_SIZE, &cp_ring_);
238	    if (r != VX_SUCCESS) return r;
239	    r = host_alloc(CP_CL_BYTES, &cp_head_);
240	    if (r != VX_SUCCESS) return r;
241	    r = host_alloc(CP_CL_BYTES, &cp_cmpl_);
242	    if (r != VX_SUCCESS) return r;
243	
244	    // Zero them so the CP doesn't read stale data on first fetch.
245	    std::memset(cp_ring_.host_ptr, 0, CP_RING_SIZE);
246	    std::memset(cp_head_.host_ptr, 0, CP_CL_BYTES);
247	    std::memset(cp_cmpl_.host_ptr, 0, CP_CL_BYTES);
248	
249	    // Program CP queue 0. Any failure here is fatal — the CP regfile is
250	    // the sole control path, so a botched setup means cp_enabled_=true
251	    // would lie about a working device. Macro keeps the call list legible.
252	    #define CP_WR(_off, _val) do {                                          \
253	        auto _r = p->cp_reg_write((_off), (_val));                          \
254	        if (_r != VX_SUCCESS) return _r;                                    \
255	    } while (0)
256	    CP_WR(CP_Q_RING_BASE_LO,   uint32_t(cp_ring_.cp_addr & 0xFFFFFFFFu));
257	    CP_WR(CP_Q_RING_BASE_HI,   uint32_t(cp_ring_.cp_addr >> 32));
258	    CP_WR(CP_Q_HEAD_ADDR_LO,   uint32_t(cp_head_.cp_addr & 0xFFFFFFFFu));
259	    CP_WR(CP_Q_HEAD_ADDR_HI,   uint32_t(cp_head_.cp_addr >> 32));
260	    CP_WR(CP_Q_CMPL_ADDR_LO,   uint32_t(cp_cmpl_.cp_addr & 0xFFFFFFFFu));
261	    CP_WR(CP_Q_CMPL_ADDR_HI,   uint32_t(cp_cmpl_.cp_addr >> 32));
262	    CP_WR(CP_Q_RING_SIZE_LOG2, CP_RING_SIZE_LOG2);
263	    CP_WR(CP_Q_CONTROL,        0x1);
264	    CP_WR(CP_REG_CTRL,         0x1);
265	
266	    cp_enabled_ = true;
267	
268	    // Discover VM support at runtime: the CP publishes VM_ENABLED in DEV_CAPS
269	    // (bit 24); read once here rather than relying on compile-time #ifdefs.
270	    {
271	        uint32_t dev_caps = 0;
272	        if (p->cp_reg_read(CP_DEV_CAPS, &dev_caps) != VX_SUCCESS)
273	            return VX_ERR_DEVICE_LOST;
274	        vm_enabled_ = (dev_caps & (1u << 24)) != 0;
275	        // SUPPORTS_DRAW (bit 25): the CP decodes CMD_DRAW (OP_DRAW). When clear
276	        // (e.g. an RTL CP without the OP_DRAW mirror yet), vx_enqueue_draw falls
277	        // back to streaming the draw as a ring batch (functionally identical).
278	        cp_supports_draw_ = (dev_caps & (1u << 25)) != 0;
279	        // SUPPORTS_QMD (bit 26): the CP decodes CMD_LAUNCH_QMD. When clear,
280	        // launches replay the staged descriptor as plain CMD_DCR_WRITEs
281	        // followed by CMD_LAUNCH (functionally identical, more ring commands).
282	        cp_supports_qmd_ = (dev_caps & (1u << 26)) != 0;
283	    }
284	
285	    if (vm_enabled_) {
286	        // Virtual memory: build the page tables and program the CP DMA's MMU
287	        // with the page-table root. After this, mem_alloc mints VAs and the
288	        // CP DMA translates VA->PA per CMD_MEM_*.
289	        //
290	        // Carve the page-table region out of the device-memory allocator so
291	        // a later mem_alloc cannot hand back a PA that overlaps the page
292	        // tables. Done before any mem_alloc is reachable (still in open()).
293	        {
294	            std::lock_guard<std::mutex> g(mu_);
295	            if (global_mem_.reserve(VX_MEM_PAGE_TABLE_BASE_ADDR,
296	                                    VX_VM_PT_SIZE_LIMIT) != 0)
297	                return VX_ERR_DEVICE_LOST;
298	        }
299	        vm_io_  = std::unique_ptr<CpMemIO>(new CpMemIO(this));
300	        vm_mgr_ = std::unique_ptr<vortex::VMManager>(
301	                      new vortex::VMManager(vm_io_.get()));
302	        if (vm_mgr_->init() != 0)
303	            return VX_ERR_DEVICE_LOST;
304	        const uint64_t satp = vm_mgr_->satp();
305	        CP_WR(CP_SATP_LO, uint32_t(satp & 0xFFFFFFFFu));
306	        CP_WR(CP_SATP_HI, uint32_t(satp >> 32));
307	    }
308	    #undef CP_WR
309	
310	    // Zero the COUT stream-ring metadata (wr[]/rd[]/lost[]) so the first
311	    // drain sees empty rings and a zero overflow baseline. data[] is
312	    // overwritten by vx_putchar before being read by drain_cout, so we
313	    // skip it: zero only wr[] (offset 0), rd[] (offset SLOTS*4), and
314	    // lost[] (offset SLOTS*8 + SLOTS*RING). Routed via dev_write — on a
315	    // CP-only-DMA backend this is a CP transfer, so it must follow CP enable.
316	    {
317	        constexpr uint32_t SLOTS = VX_MEM_IO_COUT_SLOTS;
318	        constexpr uint32_t RING  = VX_MEM_IO_COUT_RING;
319	        std::vector<uint8_t> zeros_meta(SLOTS * 4, 0);
320	        // wr[] + rd[] are contiguous at the start of the region.
321	        r = dev_write(VX_MEM_IO_COUT_ADDR,
322	                      std::vector<uint8_t>(SLOTS * 8, 0).data(),
323	                      SLOTS * 8);
324	        if (r != VX_SUCCESS) return r;
325	        // lost[] sits past data[].
326	        const uint64_t LOST_BASE = VX_MEM_IO_COUT_ADDR
327	                                 + uint64_t(SLOTS) * 8
328	                                 + uint64_t(SLOTS) * RING;
329	        r = dev_write(LOST_BASE, zeros_meta.data(), zeros_meta.size());
330	        if (r != VX_SUCCESS) return r;
331	    }
332	
333	    return VX_SUCCESS;
334	}
335	
336	vx_result_t Device::cp_ring_append_(const void* cl) {
337	    // Caller holds cp_mu_. Write one CL into the ring at the current tail —
338	    // a plain memcpy through the ring's CP-visible host pointer — then bump
339	    // tail + reserve the seqnum slot. No doorbell, no poll.
340	    const uint64_t ring_off = cp_tail_ & (CP_RING_SIZE - 1);
341	    if (ring_off + CP_CL_BYTES > CP_RING_SIZE)
342	        return VX_ERR_INVALID_VALUE;  // mid-CL ring wrap not yet supported
343	    std::memcpy(static_cast<uint8_t*>(cp_ring_.host_ptr) + ring_off,
344	                cl, CP_CL_BYTES);
345	    cp_tail_           += CP_CL_BYTES;
346	    cp_expected_seqnum_ += 1;
347	    return VX_SUCCESS;
348	}
349	
350	void Device::cp_batch_begin() {
351	    cp_mu_.lock();                       // held until cp_batch_end
352	    cp_in_batch_     = true;
353	    // Baseline target: an empty batch polls for an already-retired seqnum
354	    // and returns immediately.
355	    cp_batch_target_ = cp_expected_seqnum_;
356	}
357	
358	vx_result_t Device::cp_batch_end() {
359	    auto* p = platform();
360	    const uint64_t target = cp_batch_target_;
361	    cp_in_batch_ = false;
362	
363	    // Commit the staged tail once (the single doorbell for the whole batch),
364	    // while still holding cp_mu_ from cp_batch_begin. Release fence first so
365	    // the CP cannot read a stale ring entry (see cp_submit_cl_).
366	    std::atomic_thread_fence(std::memory_order_release);
367	    auto r = p->cp_reg_write(CP_Q_TAIL_LO, uint32_t(cp_tail_ & 0xFFFFFFFFu));
368	    if (r == VX_SUCCESS)
369	        r = p->cp_reg_write(CP_Q_TAIL_HI, uint32_t(cp_tail_ >> 32));
370	    cp_mu_.unlock();                     // release the batch lock before polling
371	    if (r != VX_SUCCESS) return r;
372	
373	    // Poll Q_SEQNUM once for the last command in the batch. Reacquire cp_mu_
374	    // around each MMIO read so simx's tick() and concurrent posts don't race.
375	    for (;;) {
376	        uint32_t seqnum32 = 0;
377	        {
378	            std::lock_guard<std::mutex> g(cp_mu_);
379	            r = p->cp_reg_read(CP_Q_SEQNUM, &seqnum32);
380	        }
381	        if (r != VX_SUCCESS) return r;
382	        if (uint64_t(seqnum32) >= target) break;
383	    #ifdef SCOPE
384	        (void)vx_scope_drain();
385	    #endif
386	    }
387	    // The batch's trailing CMD_CACHE_FLUSH(es) have retired, so every kernel's
388	    // writes are coherent: drain the console rings once for the whole batch
389	    // (deferred from each in-batch cp_submit_launch).
390	    return drain_cout();
391	}
392	
393	vx_result_t Device::cp_submit_cl_(const void* cl) {
394	    auto* p = platform();
395	
396	    // Batch mode: append only — cp_mu_ is already held for the batch, and
397	    // the single doorbell + poll happen in cp_batch_end.
398	    if (cp_in_batch_) {
399	        auto r = cp_ring_append_(cl);
400	        if (r == VX_SUCCESS) cp_batch_target_ = cp_expected_seqnum_;
401	        return r;
402	    }
403	
404	    uint64_t target;
405	    {
406	        // Hold cp_mu_ only through ring write + TAIL doorbell; release before
407	        // polling so concurrent CMD_EVENT_WAIT submitters can post SIGNALs that
408	        // unblock a stalled WAIT at the ring head.
409	        std::lock_guard<std::mutex> g(cp_mu_);
410	
411	        // 1) Write the CL into the ring and reserve its seqnum.
412	        auto r = cp_ring_append_(cl);
413	        if (r != VX_SUCCESS) return r;
414	        target = cp_expected_seqnum_;
415	
416	        // Release fence between the ring memcpy and the doorbell MMIO so
417	        // the CP cannot read a stale ring entry. The MMIO write is a
418	        // serializing UC store on x86 (sfence-equivalent), but on ARM /
419	        // RISC-V and on shells that map host_only BOs WB this fence is
420	        // required for correctness. Cheap on x86; matters everywhere else.
421	        std::atomic_thread_fence(std::memory_order_release);
422	
423	        // 2) Commit the new tail. Atomic-pair: LO stages, HI commits both.
424	        r = p->cp_reg_write(CP_Q_TAIL_LO, uint32_t(cp_tail_ & 0xFFFFFFFFu));
425	        if (r != VX_SUCCESS) return r;
426	        r = p->cp_reg_write(CP_Q_TAIL_HI, uint32_t(cp_tail_ >> 32));
427	        if (r != VX_SUCCESS) return r;
428	    }   // release cp_mu_ — another submitter can now post its own command
429	
430	    // 3) Poll Q_SEQNUM. Reacquire cp_mu_ around each individual MMIO read
431	    // so simx's tick() (which mutates simulator state) and concurrent
432	    // posts from other queues don't race; this still leaves a window
433	    // between iterations for other submitters to come in.
434	    for (;;) {
435	        uint32_t seqnum32 = 0;
436	        vx_result_t r;
437	        {
438	            std::lock_guard<std::mutex> g(cp_mu_);
439	            r = p->cp_reg_read(CP_Q_SEQNUM, &seqnum32);
440	        }
441	        if (r != VX_SUCCESS) return r;
442	        if (uint64_t(seqnum32) >= target) return VX_SUCCESS;
443	        // COUT is drained post-launch only (see cp_submit_launch). The CP
444	        // ring is serial — a COUT CMD_MEM_READ posted here would queue
445	        // behind the very command being waited on; mid-launch draining is not
446	        // possible on a single-queue CP. A kernel that overruns its COUT ring
447	        // within one launch back-pressures until the launch ends.
448	    #ifdef SCOPE
449	        // Same discipline for the SCOPE tap rings: drain continuously so
450	        // the on-chip ring pauses capture only briefly. Best-effort.
451	        (void)vx_scope_drain();
452	    #endif
453	        // No host sleep: each MMIO read already ticks sim cycles.
454	    }
455	}
456	
457	vx_result_t Device::cp_submit_dcr_write(uint32_t addr, uint32_t value) {
458	    // VM safety check: when VM is active and the pinned slab is configured,
459	    // every HW-addr DCR must reference a buffer in the pinned slab — the HW
460	    // master bypasses the per-core MMU and would otherwise dereference a stale VA.
461	    //
462	    // TEX / RASTER / OM address DCRs encode value as a cache-block index
463	    // (pa = value << 6). Split BASE_LO/HI DCR pairs (e.g. DXA) are validated
464	    // by the caller, not here.
465	    if (vm_enabled_ && pinned_mem_) {
466	        switch (addr) {
467	        case VX_DCR_TEX_ADDR:
468	        case VX_DCR_RASTER_TBUF_ADDR:
469	        case VX_DCR_RASTER_PBUF_ADDR:
470	        case VX_DCR_OM_CBUF_ADDR:
471	        case VX_DCR_OM_ZBUF_ADDR: {
472	            const uint64_t pa = uint64_t(value) << 6;
473	            if (pa < pinned_base_ ||
474	                pa >= pinned_base_ + pinned_size_) {
475	                std::cerr << "[VXDRV] dcr 0x" << std::hex << addr
476	                          << " value 0x" << value << " (pa 0x" << pa
477	                          << ") not in pinned slab [0x" << pinned_base_
478	                          << ", 0x" << (pinned_base_ + pinned_size_)
479	                          << ") — buffer needs VX_MEM_PHYS"
480	                          << std::dec << std::endl;
481	                return VX_ERR_INVALID_VALUE;
482	            }
483	            break;
484	        }
485	        default:
486	            break;
487	        }
488	    }
489	    // CMD_DCR_WRITE on-wire layout (cmd_size=20):
490	    //   bytes 0..3   header  { opcode=0x04, flags=0, reserved=0 }
491	    //   bytes 4..11  arg0    DCR addr
492	    //   bytes 12..19 arg1    DCR value
493	    // Rest of CL is padded with zeros (NOP sentinel for the unpacker).
494	    uint8_t cl[CP_CL_BYTES] = {0};
495	    uint32_t* p32 = reinterpret_cast<uint32_t*>(cl);
496	    p32[0] = CP_OPCODE_DCR_WR;
497	    p32[1] = addr;
498	    p32[3] = value;
499	    return cp_submit_cl_(cl);
500	}
501	
502	vx_result_t Device::cp_submit_launch() {
503	    // CMD_LAUNCH on-wire layout (cmd_size=12):
504	    //   bytes 0..3   header  { opcode=0x06, flags=0, reserved=0 }
505	    //   bytes 4..11  arg0    unused by VX_cp_launch
506	    uint8_t cl[CP_CL_BYTES] = {0};
507	    cl[0] = CP_OPCODE_LAUNCH;
508	    auto r = cp_submit_cl_(cl);
509	    if (r != VX_SUCCESS) return r;
510	    // Cache coherence: post an explicit cache flush right after the launch
511	    // (ACQUIRE_MEM model) so the host observes coherent kernel results.
512	    r = cp_submit_cache_flush();
513	    if (r != VX_SUCCESS) return r;
514	    // In a batch the flush has only been appended, not retired — defer the
515	    // COUT drain to cp_batch_end (one drain for the whole sequence).
516	    if (cp_in_batch_) return VX_SUCCESS;
517	    // Final COUT drain: the flush has made the kernel's writes coherent, so
518	    // the tail-end console output left in the rings is now safe to read.
519	    return drain_cout();
520	}
521	
522	vx_result_t Device::cp_submit_launch_qmd(uint64_t qmd_addr) {
523	    // CMD_LAUNCH_QMD on-wire layout (cmd_size=12):
524	    //   bytes 0..3   header  { opcode=0x0B, flags=0, reserved=0 }
525	    //   bytes 4..11  arg0    QMD descriptor device address
526	    // The CP reads the in-memory KMU descriptor (a {count,(addr,value)...}
527	    // list the caller staged) and replays it before pulsing start — one ring
528	    // command in place of the ~18 CMD_DCR_WRITEs a plain launch costs. Same
529	    // trailing CMD_CACHE_FLUSH / COUT-drain discipline as cp_submit_launch.
530	    uint8_t cl[CP_CL_BYTES] = {0};
531	    cl[0] = CP_OPCODE_LAUNCH_QMD;
532	    std::memcpy(cl + 4, &qmd_addr, sizeof(qmd_addr));
533	    auto r = cp_submit_cl_(cl);
534	    if (r != VX_SUCCESS) return r;
535	    r = cp_submit_cache_flush();
536	    if (r != VX_SUCCESS) return r;
537	    if (cp_in_batch_) return VX_SUCCESS;
538	    return drain_cout();
539	}
540	
541	vx_result_t Device::cp_submit_draw(uint64_t desc_addr) {
542	    // CMD_DRAW on-wire layout (cmd_size=12):
543	    //   bytes 0..3   header  { opcode=0x0C, flags=0, reserved=0 }
544	    //   bytes 4..11  arg0    draw descriptor device address
545	    // The CP reads the resident descriptor ({num_steps, 28-byte cmd steps...})
546	    // and executes the embedded bundle in order — draining each launch (the
547	    // inter-stage barrier) on-device. The descriptor's per-stage CACHE_FLUSH
548	    // steps make results coherent; a final COUT drain mirrors cp_submit_launch_qmd.
549	    uint8_t cl[CP_CL_BYTES] = {0};
550	    cl[0] = CP_OPCODE_DRAW;
551	    std::memcpy(cl + 4, &desc_addr, sizeof(desc_addr));
552	    auto r = cp_submit_cl_(cl);
553	    if (r != VX_SUCCESS) return r;
554	    if (cp_in_batch_) return VX_SUCCESS;
555	    return drain_cout();
556	}
557	
558	vx_result_t Device::cp_submit_cache_flush() {
559	    // CMD_CACHE_FLUSH on-wire layout (cmd_size=12):
560	    //   bytes 0..3   header  { opcode=0x0A, flags=0, reserved=0 }
561	    //   bytes 4..11  arg0    number of cores to flush
562	    // The CP sweeps a per-core flush DCR-read across [0, num_cores) and
563	    // retires the command only when the last core's flush completes.
564	    // No-op on write-through cache configs (the Vortex default).
565	    if (cp_num_cores_ == 0) {
566	        auto r = this->query_caps(VX_CAPS_NUM_CORES, &cp_num_cores_);
567	        if (r != VX_SUCCESS) return r;
568	    }
569	    uint8_t cl[CP_CL_BYTES] = {0};
570	    cl[0] = CP_OPCODE_CACHE_FLUSH;
571	    std::memcpy(cl + 4, &cp_num_cores_, sizeof(cp_num_cores_));
572	    return cp_submit_cl_(cl);
573	}
