575	vx_result_t Device::cp_submit_dcr_read(uint32_t addr, uint32_t tag,
576	                                       uint32_t* out_value) {
577	    if (!out_value) return VX_ERR_INVALID_VALUE;
578	    // CMD_DCR_READ on-wire layout (cmd_size=20):
579	    //   bytes 0..3   header  { opcode=0x05, flags=0, reserved=0 }
580	    //   bytes 4..11  arg0    DCR addr (low 12 bits used)
581	    //   bytes 12..19 arg1    tag (data on the DCR bus; e.g. core index
582	    //                        for VX_DCR_BASE_CACHE_FLUSH)
583	    uint8_t cl[CP_CL_BYTES] = {0};
584	    uint32_t* p32 = reinterpret_cast<uint32_t*>(cl);
585	    p32[0] = CP_OPCODE_DCR_RD;
586	    p32[1] = addr;
587	    p32[3] = tag;
588	    auto r = cp_submit_cl_(cl);
589	    if (r != VX_SUCCESS) return r;
590	    // Pick up the response from the CP regfile: VX_cp_dcr_proxy latches
591	    // it on Q_LAST_DCR_RSP at the same offset as the engine's retire.
592	    return platform()->cp_reg_read(CP_Q_LAST_DCR_RSP, out_value);
593	}
594	
595	// CMD_EVENT_SIGNAL / CMD_EVENT_WAIT (opcodes 0x08 / 0x09) are implemented by
596	// the RTL CP's VX_cp_event_unit but are intentionally not driven by the host
597	// runtime: on a single in-order CP ring shared by every queue, a blocking
598	// device-side wait at the ring head stalls all commands behind it — including
599	// a producer's signal posted from another queue — so cross-queue
600	// wait-before-signal deadlocks. Timeline events are resolved host-side instead
601	// (see Event / Queue::enqueue_wait_value). Device-side semaphores can return
602	// once the CP exposes independent rings per queue.
603	
604	// ============================================================================
605	// CP-driven host<->device DMA (CMD_MEM_*)
606	// ============================================================================
607	
608	vx_result_t Device::cp_submit_mem_(uint8_t opcode, uint64_t arg0,
609	                                   uint64_t arg1, uint64_t arg2,
610	                                   bool physical) {
611	    // CMD_MEM_* on-wire layout (cmd_size=28):
612	    //   bytes 0..3   header  { opcode, flags, reserved=0 }
613	    //   bytes 4..11  arg0    dst address
614	    //   bytes 12..19 arg1    src address
615	    //   bytes 20..27 arg2    size in bytes
616	    uint8_t cl[CP_CL_BYTES] = {0};
617	    cl[0] = opcode;
618	    cl[1] = physical ? CP_MEM_FLAG_PHYSICAL : 0;   // skip CP-DMA VM translation
619	    std::memcpy(cl + 4,  &arg0, sizeof(arg0));
620	    std::memcpy(cl + 12, &arg1, sizeof(arg1));
621	    std::memcpy(cl + 20, &arg2, sizeof(arg2));
622	    return cp_submit_cl_(cl);
623	}
