625	vx_result_t Device::cp_submit_mem_copy(uint64_t dst, uint64_t src,
626	                                       uint64_t size) {
627	    if (size == 0 || dst == src) return VX_SUCCESS;
628	    return cp_submit_mem_(CP_OPCODE_MEM_COPY, dst, src, size);
629	}
