631	vx_result_t Device::cp_submit_mem_write(uint64_t dev_dst, const void* host_src,
632	                                        uint64_t size, bool physical) {
633	    if (size == 0)  return VX_SUCCESS;
634	    if (!host_src)  return VX_ERR_INVALID_VALUE;
635	    // Stage the payload into CP-visible host memory (a plain memcpy through
636	    // the host pointer), then have the CP DMA it to device memory. `physical`
637	    // (set for page-table writes) tells the CP DMA to skip VM translation.
638	    HostMem staging;
639	    auto r = host_alloc(size, &staging);
640	    if (r != VX_SUCCESS) return r;
641	    std::memcpy(staging.host_ptr, host_src, size);
642	    r = cp_submit_mem_(CP_OPCODE_MEM_WRITE, dev_dst, staging.cp_addr, size,
643	                       physical);
644	    host_free(staging.cp_addr);
645	    return r;
646	}
