648	vx_result_t Device::cp_submit_mem_read(void* host_dst, uint64_t dev_src,
649	                                       uint64_t size, bool physical) {
650	    if (size == 0)  return VX_SUCCESS;
651	    if (!host_dst)  return VX_ERR_INVALID_VALUE;
652	    // Have the CP DMA device->host into a CP-visible host staging buffer,
653	    // then memcpy it back to the caller's pointer.
654	    HostMem staging;
655	    auto r = host_alloc(size, &staging);
656	    if (r != VX_SUCCESS) return r;
657	    r = cp_submit_mem_(CP_OPCODE_MEM_READ, staging.cp_addr, dev_src, size,
658	                       physical);
659	    if (r == VX_SUCCESS)
660	        std::memcpy(host_dst, staging.host_ptr, size);
661	    host_free(staging.cp_addr);
662	    return r;
663	}
