691	vx_result_t Device::mem_alloc(uint64_t size, uint32_t flags,
692	                              uint64_t* out_addr) {
693	    if (!out_addr || size == 0) return VX_ERR_INVALID_VALUE;
694	    if (flags & VX_MEM_HOST) {
695	        // CP-visible host memory — the cp_addr doubles as the handle.
696	        HostMem hm;
697	        auto r = host_alloc(size, &hm);
698	        if (r != VX_SUCCESS) return r;
699	        *out_addr = hm.cp_addr;
700	        return VX_SUCCESS;
701	    }
702	    const uint64_t asize =
703	        (size + CACHE_BLOCK_SIZE - 1) & ~uint64_t(CACHE_BLOCK_SIZE - 1);
704	    // Route PHYS allocations to the pinned slab when configured; everything
705	    // else comes from global_mem_. PHYS exhaustion is a hard fail
706	    // (VX_ERR_OUT_OF_DEVICE_MEMORY) — silent fallback to the paged pool
707	    // would cause PA fragmentation in the identity-mapped region.
708	    const bool from_pinned = (flags & VX_MEM_PHYS) && pinned_mem_;
709	    {
710	        std::lock_guard<std::mutex> g(mu_);
711	        auto& alloc = from_pinned ? *pinned_mem_ : global_mem_;
712	        if (alloc.allocate(asize, out_addr) != 0)
713	            return VX_ERR_OUT_OF_DEVICE_MEMORY;
714	    }
715	    // VM: *out_addr is a PA. VX_MEM_PHYS keeps it (identity-mapped so the
716	    // kernel reaches it at VA==PA); otherwise mint a fresh VA + install
717	    // PTEs so the kernel's MMU and the CP DMA both translate it. vm_mgr_ is
718	    // non-null iff the device reported an MMU at vx_device_open.
719	    if (vm_mgr_) {
720	        std::lock_guard<std::mutex> g(vm_mu_);
721	        int rc = (flags & VX_MEM_PHYS)
722	                   ? vm_mgr_->install_identity_map(*out_addr, asize)
723	                   : vm_mgr_->phy_to_virt_map(asize, out_addr, flags);
724	        if (rc != 0) return VX_ERR_INVALID_VALUE;
725	    }
726	    return VX_SUCCESS;
727	}
728	
729	vx_result_t Device::mem_reserve(uint64_t addr, uint64_t size, uint32_t flags) {
730	    (void)flags;
731	    if (size == 0) return VX_ERR_INVALID_VALUE;
732	    const uint64_t asize =
733	        (size + CACHE_BLOCK_SIZE - 1) & ~uint64_t(CACHE_BLOCK_SIZE - 1);
734	    // Caller-chosen PA: dispatch by address to whichever allocator owns
735	    // the range. The pinned slab sits at [pinned_base_, pinned_base_ +
736	    // pinned_size_); everything else is in global_mem_. reserve() on the
737	    // wrong pool would unconditionally fail, so picking the right one
738	    // here lets reservations into the pinned slab succeed.
739	    const bool in_pinned = pinned_mem_
740	        && addr >= pinned_base_
741	        && addr + asize <= pinned_base_ + pinned_size_;
742	    {
743	        std::lock_guard<std::mutex> g(mu_);
744	        auto& alloc = in_pinned ? *pinned_mem_ : global_mem_;
745	        if (alloc.reserve(addr, asize) != 0)
746	            return VX_ERR_INVALID_VALUE;
747	    }
748	    // VM: a reserved region sits at a caller-chosen PA — identity-map it
749	    // (VA == PA) so the kernel reaches it at the same address.
750	    if (vm_mgr_) {
751	        std::lock_guard<std::mutex> g(vm_mu_);
752	        if (vm_mgr_->install_identity_map(addr, asize) != 0)
753	            return VX_ERR_INVALID_VALUE;
754	    }
755	    return VX_SUCCESS;
756	}
757	
758	vx_result_t Device::mem_free(uint64_t addr) {
759	    bool is_host;
760	    {
761	        std::lock_guard<std::mutex> g(mu_);
762	        is_host = host_mems_.count(addr) != 0;
763	    }
764	    if (is_host) {
765	        host_free(addr);
766	        return VX_SUCCESS;
767	    }
768	    // VM: `addr` is a VA — resolve to the PA the allocator handed out.
769	    if (vm_mgr_) {
770	        std::lock_guard<std::mutex> g(vm_mu_);
771	        try { addr = vm_mgr_->page_table_walk(addr); }
772	        catch (...) { /* already unmapped — fall through to release */ }
773	    }
774	    // Dispatch by resolved PA to whichever pool owns the range. PHYS
775	    // buffers are identity-mapped so their PA falls inside the slab;
776	    // non-PHYS buffers live in global_mem_.
777	    std::lock_guard<std::mutex> g(mu_);
778	    const bool in_pinned = pinned_mem_
779	        && addr >= pinned_base_
780	        && addr < pinned_base_ + pinned_size_;
781	    auto& alloc = in_pinned ? *pinned_mem_ : global_mem_;
782	    return (alloc.release(addr) == 0)
783	               ? VX_SUCCESS : VX_ERR_INVALID_VALUE;
784	}
785	
786	vx_result_t Device::memory_info(uint64_t* out_free, uint64_t* out_used) {
787	    std::lock_guard<std::mutex> g(mu_);
788	    // Report combined paged + pinned counters — callers (mesa, hipcc)
789	    // typically want the device-wide total. Per-pool inspection is
790	    // available via VX_CAPS_VM_PINNED_SIZE / _FREE.
791	    const uint64_t pinned_free = pinned_mem_ ? pinned_mem_->free()      : 0;
792	    const uint64_t pinned_used = pinned_mem_ ? pinned_mem_->allocated() : 0;
793	    if (out_free) *out_free = global_mem_.free() + pinned_free;
794	    if (out_used) *out_used = global_mem_.allocated() + pinned_used;
795	    return VX_SUCCESS;
796	}
797	
798	vx_result_t Device::query_caps(uint32_t caps_id, uint64_t* out_value) {
799	    if (!out_value) return VX_ERR_INVALID_VALUE;
800	    // The two static caps words are read once from the CP regfile caps
801	    // window; serialize the load against concurrent cp_reg_* traffic.
802	    if (!caps_loaded_) {
803	        std::lock_guard<std::mutex> g(cp_mu_);
804	        if (!caps_loaded_) {
805	            auto rd = [this](uint32_t off, uint32_t* v) -> int {
806	                return platform_->cp_reg_read(off, v) == VX_SUCCESS ? 0 : -1;
807	            };
808	            if (vortex::load_caps(rd, &dev_caps_, &isa_caps_) != 0)
809	                return VX_ERR_DEVICE_LOST;
810	            caps_loaded_ = true;
811	        }
812	    }
813	    if (vortex::decode_caps(dev_caps_, isa_caps_, caps_id, out_value))
814	        return VX_SUCCESS;
815	    // Caps not encoded in the CP words — platform/runtime constants.
816	    switch (caps_id) {
817	    case VX_CAPS_CACHE_LINE_SIZE: *out_value = CACHE_BLOCK_SIZE;             break;
818	    case VX_CAPS_GLOBAL_MEM_SIZE: *out_value = GLOBAL_MEM_SIZE;              break;
819	    case VX_CAPS_CLOCK_RATE:      *out_value = VX_CFG_PLATFORM_CLOCK_RATE;   break;
820	    case VX_CAPS_PEAK_MEM_BW:     *out_value = VX_CFG_PLATFORM_MEMORY_PEAK_BW; break;
821	    case VX_CAPS_VM_SUPPORT:      *out_value = vm_enabled_ ? 1 : 0;          break;
822	    case VX_CAPS_VM_PINNED_SIZE:  *out_value = pinned_size_;                 break;
823	    case VX_CAPS_VM_PINNED_FREE: {
824	        std::lock_guard<std::mutex> g(mu_);
825	        *out_value = pinned_mem_ ? pinned_mem_->free() : 0;
826	        break;
827	    }
828	    default:                      return VX_ERR_INVALID_VALUE;
829	    }
830	    return VX_SUCCESS;
831	}
