850	vx_result_t Device::drain_cout() {
851	    // Drain each hart's COUT ring: read wr[] and lost[], copy out [rd,wr) bytes,
852	    // emit "#slot: <line>", surface new lost-byte deltas, and publish the
853	    // advanced rd[]. vx_putchar is non-blocking (drops + bumps lost[slot] on
854	    // full ring), so this drain has no host/kernel deadlock concern.
855	    constexpr uint32_t SLOTS = VX_MEM_IO_COUT_SLOTS;
856	    constexpr uint32_t RING  = VX_MEM_IO_COUT_RING;
857	    const uint64_t WR_BASE   = VX_MEM_IO_COUT_ADDR;
858	    const uint64_t RD_BASE   = VX_MEM_IO_COUT_ADDR + uint64_t(SLOTS) * 4;
859	    const uint64_t DATA_BASE = VX_MEM_IO_COUT_ADDR + uint64_t(SLOTS) * 8;
860	    const uint64_t LOST_BASE = DATA_BASE + uint64_t(SLOTS) * RING;
861	
862	    // dev_read/dev_write route through cp_submit_* (which take cp_mu_
863	    // themselves), so this must not hold cp_mu_ — and need not: drain_cout
864	    // is only ever called post-launch, when the CP ring is otherwise idle.
865	    uint32_t wr  [SLOTS] = {};
866	    uint32_t lost[SLOTS] = {};
867	    auto r = dev_read(wr,   WR_BASE,   sizeof(wr));
868	    if (r != VX_SUCCESS) return r;
869	    r = dev_read(lost, LOST_BASE, sizeof(lost));
870	    if (r != VX_SUCCESS) return r;
871	
872	    bool advanced = false;
873	    for (uint32_t s = 0; s < SLOTS; ++s) {
874	        const uint32_t rd = cout_rd_[s];
875	        // Surface a per-slot overflow delta: kernel atomically bumps
876	        // lost[slot] on a full-ring drop, host reports the delta and
877	        // remembers the latest value so each byte is counted exactly once.
878	        if (lost[s] != cout_lost_seen_[s]) {
879	            uint32_t delta = lost[s] - cout_lost_seen_[s];   // wrap-safe (32-bit)
880	            std::cout << "[#" << s << ": lost " << delta << " bytes]"
881	                      << std::endl;
882	            cout_lost_seen_[s] = lost[s];
883	        }
884	        if (wr[s] == rd) continue;
885	        uint32_t n = wr[s] - rd;
886	        // Defensive cap: the ring is lossy, so wr-rd should never exceed
887	        // RING. If it ever does (corrupt slot, host missed many polls),
888	        // drain only the most recent RING bytes and let the producer keep
889	        // bumping `lost`.
890	        if (n > RING) n = RING;
891	        char data[RING];
892	        r = dev_read(data, DATA_BASE + uint64_t(s) * RING, RING);
893	        if (r != VX_SUCCESS) return r;
894	        for (uint32_t i = 0; i < n; ++i) {
895	            const char c = data[(rd + i) & (RING - 1)];
896	            cout_line_[s].push_back(c);
897	            if (c == '\n') {
898	                std::cout << "#" << s << ": " << cout_line_[s] << std::flush;
899	                cout_line_[s].clear();
900	            }
901	        }
902	        cout_rd_[s] = wr[s];
903	        advanced = true;
904	    }
905	    if (advanced) {
906	        r = dev_write(RD_BASE, cout_rd_, sizeof(cout_rd_));
907	        if (r != VX_SUCCESS) return r;
908	    }
909	    return VX_SUCCESS;
910	}
