932	Queue* Device::legacy_default_queue() {
933	    // Fast path: already created.
934	    {
935	        std::lock_guard<std::mutex> g(mu_);
936	        if (legacy_q_) return legacy_q_;
937	    }
938	    // Slow path: create OUTSIDE the lock. Queue::create takes this same
939	    // mutex via register_queue, so holding it here would block.
940	    vx_queue_info_t info = {};
941	    info.struct_size = sizeof(info);
942	    info.priority    = VX_QUEUE_PRIORITY_NORMAL;
943	    info.flags       = 0;
944	    Queue* q = nullptr;
945	    if (Queue::create(this, &info, &q) != VX_SUCCESS) return nullptr;
946	    // Publish (and handle race where two threads created queues
947	    // concurrently — keep one, release the other).
948	    {
949	        std::lock_guard<std::mutex> g(mu_);
950	        if (legacy_q_) {
951	            q->release();
952	            return legacy_q_;
953	        }
954	        legacy_q_ = q;
955	    }
956	    return q;
957	}
