20	namespace vortex {
21	
22	class MemoryAllocator {
23	public:
24	  MemoryAllocator(
25	    uint64_t baseAddress,
26	    uint64_t capacity,
27	    uint32_t pageAlign,
28	    uint32_t blockAlign)
29	    : baseAddress_(baseAddress)
30	    , capacity_(capacity)
31	    , pageAlign_(pageAlign)
32	    , blockAlign_(blockAlign)
33	    , pages_(nullptr)
34	    , allocated_(0)
35	  {}
36	
37	  ~MemoryAllocator() {
38	    page_t* currPage = pages_;
39	    while (currPage) {
40	      auto nextPage = currPage->next;
41	      #ifdef VX_CFG_VM_ENABLE
42	      block_t* currblock = currPage->findfirstUsedBlock();
43	      block_t* nextblock;
44	      while (currblock) {
45	        nextblock= currblock->nextUsed;
46	        currPage->release(currblock);
47	        currblock = nextblock;
48	      }
49	      #endif
50	      delete currPage;
51	      currPage = nextPage;
52	    }
53	  }
54	
55	  uint32_t baseAddress() const {
56	    return baseAddress_;
57	  }
58	
59	  uint32_t capacity() const {
60	    return capacity_;
61	  }
62	
63	  uint64_t free() const {
64	    return (capacity_ - allocated_);
65	  }
66	
67	  uint64_t allocated() const {
68	    return allocated_;
69	  }
70	
71	  int reserve(uint64_t addr, uint64_t size) {
72	    if (size == 0) {
73	      printf("Error: invalid arguments\n");
74	      return -1;
75	    }
76	
77	    size = alignSize(size, pageAlign_);
78	
79	    // Check if the reservation is within memory capacity bounds
80	    if (addr + size > baseAddress_ + capacity_) {
81	      printf("Error: address range out of bounds - requested=0x%lx, base+capacity=0x%lx\n", (addr + size), (baseAddress_ +capacity_));
82	      return -1;
83	    }
84	
85	    // Ensure the reservation does not overlap with existing pages
86	    uint64_t overlapStart, overlapEnd;
87	    if (hasPageOverlap(addr, size, &overlapStart, &overlapEnd)) {
88	      printf("Error: address range overlaps with existing allocation - requested=[0x%lx-0x%lx], existing=[0x%lx, 0x%lx]\n", addr, addr+size, overlapStart, overlapEnd);
89	      return -1;
90	    }
91	
92	    auto newPage = this->createPage(addr, size);
93	    auto freeBlock = newPage->findFreeBlock(size);
94	    newPage->allocate(size, freeBlock);
95	    allocated_ += size;
96	
97	    return 0;
98	  }
99	
100	  int allocate(uint64_t size, uint64_t* addr) {
101	    if (size == 0 || addr == nullptr) {
102	      printf("Error: invalid arguments\n");
103	      return -1;
104	    }
105	
106	    size = alignSize(size, blockAlign_);
107	
108	    // Walk pages to find a free block
109	    block_t* freeBlock = nullptr;
110	    auto currPage = pages_;
111	    while (currPage) {
112	      freeBlock = currPage->findFreeBlock(size);
113	      if (freeBlock != nullptr)
114	        break;
115	      currPage = currPage->next;
116	    }
117	
118	    // Allocate a new page if no free block is found
119	    if (freeBlock == nullptr) {
120	      auto pageSize = alignSize(size, pageAlign_);
121	      uint64_t pageAddr;
122	      if (!this->findNextAddress(pageSize, &pageAddr)) {
123	        printf("Error: out of memory (Can't find next address)\n");
124	        return -1;
125	      }
126	      currPage = this->createPage(pageAddr, pageSize);
127	      if (nullptr == currPage) {
128	        printf("Error: out of memory (Can't create a page)\n");
129	        return -1;
130	      }
131	      freeBlock = currPage->findFreeBlock(size);
132	    }
133	
134	    currPage->allocate(size, freeBlock);
135	    *addr = freeBlock->addr;
136	    allocated_ += size;
137	
138	    return 0;
139	  }
140	
141	  int release(uint64_t addr) {
142	    block_t* usedBlock = nullptr;
143	    auto currPage = pages_;
144	    while (currPage) {
145	      usedBlock = currPage->findUsedBlock(addr);
146	      if (usedBlock != nullptr)
147	        break;
148	      currPage = currPage->next;
149	    }
150	
151	    if (nullptr == usedBlock) {
152	      printf("warning: release address not found: 0x%lx\n", addr);
153	      return -1;
154	    }
155	
156	    auto size = usedBlock->size;
157	    currPage->release(usedBlock);
158	    if (currPage->empty()) {
159	      this->deletePage(currPage);
160	    }
161	    allocated_ -= size;
162	
163	    return 0;
164	  }
165	
166	private:
167	
168	  struct block_t {
169	    block_t* nextFreeS;
170	    block_t* prevFreeS;
171	
172	    block_t* nextFreeM;
173	    block_t* prevFreeM;
174	
175	    block_t* nextUsed;
176	    block_t* prevUsed;
177	
178	    uint64_t addr;
179	    uint64_t size;
180	
181	    block_t(uint64_t addr, uint64_t size)
182	      : nextFreeS(nullptr)
183	      , prevFreeS(nullptr)
184	      , nextFreeM(nullptr)
185	      , prevFreeM(nullptr)
186	      , nextUsed(nullptr)
187	      , prevUsed(nullptr)
188	      , addr(addr)
189	      , size(size)
190	    {}
191	  };
192	
193	  struct page_t {
194	    page_t*  next;
195	    uint64_t addr;
196	    uint64_t size;
197	
198	    page_t(uint64_t addr, uint64_t size, uint32_t blockAlign) :
199	      next(nullptr),
200	      addr(addr),
201	      size(size),
202	      blockAlign_(blockAlign),
203	      usedList_(nullptr) {
204	      freeSList_ = freeMList_ = new block_t(addr, size);
205	    }
206	
207	    ~page_t() {
208	      // The page should be empty
209	      assert(nullptr == usedList_);
210	      assert(freeMList_
211	          && (nullptr == freeMList_->nextFreeM)
212	          && (nullptr == freeMList_->prevFreeM));
213	      delete freeMList_;
214	    }
215	
216	    bool empty() const {
217	      return (usedList_ == nullptr);
218	    }
219	
220	    void allocate(uint64_t size, block_t* freeBlock) {
221	      this->removeFreeMList(freeBlock);
222	      this->removeFreeSList(freeBlock);
223	
224	      // Split the free block if larger than needed.
225	      uint64_t extraBytes = freeBlock->size - size;
226	      if (extraBytes >= blockAlign_) {
227	        freeBlock->size = size;
228	        auto nextAddr = freeBlock->addr + size;
229	        auto newBlock = new block_t(nextAddr, extraBytes);
230	        this->insertFreeMList(newBlock);
231	        this->insertFreeSList(newBlock);
232	      }
233	
234	      this->insertUsedList(freeBlock);
235	    }
236	
237	    void release(block_t* usedBlock) {
238	      this->removeUsedList(usedBlock);
239	      this->insertFreeMList(usedBlock);
240	
241	      // Merge adjacent free blocks from the left.
242	      if (usedBlock->prevFreeM) {
243	        auto prevAddr = usedBlock->prevFreeM->addr + usedBlock->prevFreeM->size;
244	        if (usedBlock->addr == prevAddr) {
245	          auto prevBlock = usedBlock->prevFreeM;
246	          prevBlock->size += usedBlock->size;
247	          prevBlock->nextFreeM = usedBlock->nextFreeM;
248	          if (prevBlock->nextFreeM) {
249	            prevBlock->nextFreeM->prevFreeM = prevBlock;
250	          }
251	          // Detach prev from S-list since its size grew.
252	          this->removeFreeSList(prevBlock);
253	          delete usedBlock;
254	          usedBlock = prevBlock;
255	        }
256	      }
257	
258	      // Merge adjacent free blocks from the right.
259	      if (usedBlock->nextFreeM) {
260	        auto nextAddr = usedBlock->addr + usedBlock->size;
261	        if (usedBlock->nextFreeM->addr == nextAddr) {
262	          auto nextBlock = usedBlock->nextFreeM;
263	          usedBlock->size += nextBlock->size;
264	          usedBlock->nextFreeM = nextBlock->nextFreeM;
265	          if (usedBlock->nextFreeM) {
266	            usedBlock->nextFreeM->prevFreeM = usedBlock;
267	          }
268	          this->removeFreeSList(nextBlock);
269	          delete nextBlock;
270	        }
271	      }
272	
273	      this->insertFreeSList(usedBlock);
274	    }
275	
276	    block_t* findFreeBlock(uint64_t size) {
277	      auto freeBlock = freeSList_;
278	      if (freeBlock) {
279	        // S-list is sorted largest-first; find the smallest block that fits.
280	        if (freeBlock->size >= size) {
281	          while (freeBlock->nextFreeS && (freeBlock->nextFreeS->size >= size)) {
282	            freeBlock = freeBlock->nextFreeS;
283	          }
284	          return freeBlock;
285	        }
286	      }
287	      return nullptr;
288	    }
289	
290	    block_t* findUsedBlock(uint64_t addr) {
291	      if (addr >= this->addr && addr < (this->addr + this->size)) {
292	        auto useBlock = usedList_;
293	        while (useBlock) {
294	          if (useBlock->addr == addr)
295	            return useBlock;
296	          useBlock = useBlock->nextUsed;
297	        }
298	      }
299	      return nullptr;
300	    }
301	#ifdef VX_CFG_VM_ENABLE
302	    block_t* findfirstUsedBlock() {
303	      return usedList_;
304	    }
305	#endif
306	
307	  private:
308	
309	    void insertUsedList(block_t* block) {
310	      block->nextUsed = usedList_;
311	      if (usedList_) {
312	        usedList_->prevUsed = block;
313	      }
314	      usedList_ = block;
315	    }
316	
317	    void removeUsedList(block_t* block) {
318	      if (block->prevUsed) {
319	        block->prevUsed->nextUsed = block->nextUsed;
320	      } else {
321	        usedList_ = block->nextUsed;
322	      }
323	      if (block->nextUsed) {
324	        block->nextUsed->prevUsed = block->prevUsed;
325	      }
326	      block->nextUsed = nullptr;
327	      block->prevUsed = nullptr;
328	    }
329	
330	    void insertFreeMList(block_t* block) {
331	      block_t* currBlock = freeMList_;
332	      block_t* prevBlock = nullptr;
333	      while (currBlock && (currBlock->addr < block->addr)) {
334	        prevBlock = currBlock;
335	        currBlock = currBlock->nextFreeM;
336	      }
337	      block->nextFreeM = currBlock;
338	      block->prevFreeM = prevBlock;
339	      if (prevBlock) {
340	        prevBlock->nextFreeM = block;
341	      } else {
342	        freeMList_ = block;
343	      }
