27	// Helper: enqueue an operation that produces an event, then wait on it
28	// synchronously and release the event.
29	template <typename Fn>
30	vx_result_t enqueue_and_wait(Device* dev, Fn&& fn) {
31	    Queue* q = dev->legacy_default_queue();
32	    if (!q) return VX_ERR_OUT_OF_HOST_MEMORY;
33	    vx_event_h ev = nullptr;
34	    auto r = fn(to_handle(q), &ev);
35	    if (r != VX_SUCCESS) return r;
36	    if (ev) {
37	        r = vx_event_wait_value(ev, 1, VX_TIMEOUT_INFINITE);
38	        vx_event_release(ev);
39	    }
40	    return r;
