55	    if (!hdevice) return -1;
56	    // Drain any in-flight legacy launch first so the worker thread does not
57	    // outlive the device.
58	    Device* dev = to_device(hdevice);
59	    if (Event* last = dev->legacy_take_last_event()) {
60	        last->wait(VX_TIMEOUT_INFINITE);
61	        last->release();
62	    }
