203	        { VX_DCR_KMU_BLOCK_DIM_Z,   full_block[2] },
204	        { VX_DCR_KMU_GRID_DIM_X,    full_grid[0]  },
205	        { VX_DCR_KMU_GRID_DIM_Y,    full_grid[1]  },
206	        { VX_DCR_KMU_GRID_DIM_Z,    full_grid[2]  },
