208	        { VX_DCR_KMU_BLOCK_SIZE,    block_size    },
209	        { VX_DCR_KMU_WARP_STEP_X,   warp_step_x   },
210	        { VX_DCR_KMU_WARP_STEP_Y,   warp_step_y   },
211	        { VX_DCR_KMU_WARP_STEP_Z,   warp_step_z   },
212	        { VX_DCR_KMU_CLUSTER_DIM_X, 1 },
213	        { VX_DCR_KMU_CLUSTER_DIM_Y, 1 },
