25	extern int vx_upload_kernel_bytes(vx_device_h hdevice, const void* content, uint64_t size, vx_buffer_h* hbuffer) {
26	  if (nullptr == hdevice || nullptr == content || size <= 8 || nullptr == hbuffer)
27	    return -1;
28	
29	  auto bytes = reinterpret_cast<const uint64_t*>(content);
30	
31	  auto min_vma = *bytes++;
32	  auto max_vma = *bytes++;
33	  auto bin_size = size - 2 * 8;
34	  auto runtime_size = (max_vma - min_vma);
35	
36	  vx_buffer_h _hbuffer;
37	  CHECK_ERR(vx_mem_reserve(hdevice, min_vma, runtime_size, 0, &_hbuffer), {
38	    return err;
39	  });
40	
41	  // mask binary region as read-only
42	  CHECK_ERR(vx_mem_access(_hbuffer, 0, bin_size, VX_MEM_READ), {
43	    vx_mem_free(_hbuffer);
44	    return err;
45	  });
46	
47	  // mark global variables region as read-write
48	  CHECK_ERR(vx_mem_access(_hbuffer, bin_size, runtime_size - bin_size, VX_MEM_READ_WRITE), {
49	    vx_mem_free(_hbuffer);
50	    return err;
51	  });
52	
